def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([0, 0, 0]), fmt(list(range(10))), fmt(list(range(9, -1, -1))), fmt([3, 0, 9, 3, 1]),
             fmt([rng.randint(0, 9) for _ in range(100)]), fmt([9] * 100), fmt([0, 9, 0, 9, 0])]
    for n in (2, 3, 5, 8, 13, 40, 99, 100, 100):
        tests.append(fmt([rng.randint(0, 9) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 9) for _ in range(5000)]))
    for _ in range(3):
        tests.append(fmt([rng.randint(0, 9) for _ in range(500000)]))
    tests.append(fmt([rng.choice([0, 9]) for _ in range(500000)]))
